import { read } from "@/lib/data"
import { reads } from "@/lib/queries"

export const dynamic = "force-dynamic"

/** Eval ids are generated by RUN_EVAL; anything else is refused before binding. */
const EVAL_ID = /^eval_[0-9_]+$/

/**
 * Evaluation, promotion and monitoring data.
 *
 *   (no params)          -> scorecards, gate, gate config, candidate leaderboard,
 *                           promotion log, per-eval segment summary, gap review,
 *                           and the TEST DATA scenario scorecard
 *   ?evalIds=a,b         -> per-segment rows for up to 4 evals (candidate vs
 *                           champion side by side)
 */
export async function GET(req: Request) {
  try {
    const evalIdsRaw = new URL(req.url).searchParams.get("evalIds")
    if (evalIdsRaw) {
      const evalIds = evalIdsRaw
        .split(",")
        .map((s) => s.trim())
        .filter((s) => EVAL_ID.test(s))
        .slice(0, 4)
      if (evalIds.length === 0) return Response.json({ segments: [] })
      return Response.json({ segments: await read(reads.evalSegments(evalIds)) })
    }

    const [
      scorecards,
      gate,
      gateConfig,
      leaderboard,
      promotionLog,
      segmentSummary,
      gapReview,
      testScenarios,
    ] = await Promise.all([
      read(reads.scorecards()),
      read(reads.evalGate()),
      read(reads.gateConfig()),
      read(reads.leaderboard()),
      read(reads.promotionLog()),
      read(reads.segmentSummary()),
      read(reads.gapReview()),
      read(reads.testScenarioScorecard()),
    ])

    return Response.json({
      scorecards,
      gate,
      gateConfig: gateConfig[0] ?? null,
      leaderboard,
      promotionLog,
      segmentSummary,
      gapReview,
      testScenarios,
    })
  } catch (e) {
    console.error(new Date().toISOString(), "[api/eval] failed", e)
    return Response.json(
      { error: e instanceof Error ? e.message : "Failed to load evaluation" },
      { status: 500 },
    )
  }
}
